args.sql:
WITH ranked AS (
 SELECT player_api_id, preferred_foot, attacking_work_rate,
 ROW_NUMBER() OVER (PARTITION BY player_api_id ORDER BY date DESC, id DESC) AS rn
 FROM Player_Attributes
), eligible AS (
 SELECT * FROM ranked WHERE rn=1 AND preferred_foot='left' AND attacking_work_rate IS NOT NULL AND TRIM(attacking_work_rate)<>''
)
SELECT ROUND(100.0 * SUM(CASE WHEN LOWER(attacking_work_rate)='low' THEN 1 ELSE 0 END) / COUNT(*), 1) AS percentage
FROM eligible;

